package money

import (
    "fmt"
    "strconv"
)

type Amount int64

func (a Amount) Add(b Amount) Amount { return a + b }

func ParseMinor(raw string) (Amount, error) {
    n, err := strconv.ParseInt(raw, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("parse minor amount %q: %w", raw, err)
    }
    return Amount(n), nil
}
